import { useStore } from './store';

let ipcRenderer;
export const quit = () => ipcRenderer?.send('quit');
export const show = () => ipcRenderer?.send('show');
export const anchor = () => ipcRenderer?.send('anchor');
export const unanchor = () => ipcRenderer?.send('unanchor');
export const resize = size => ipcRenderer?.send('resize', { ...size });

export const init = ({ onClickCall }) => {
  try {
    ipcRenderer = window.require('electron').ipcRenderer;

    const { size, setState } = useStore.getState();

    useStore.subscribe(state => state.size, resize);

    useStore.subscribe(
      state => state.doquit,
      doquit => doquit && quit()
    );

    useStore.subscribe(
      state => state.anchored,
      anchored => (anchored ? anchor() : unanchor())
    );

    ipcRenderer.on('anchored', (_, { anchored }) => setState({ anchored }));
    ipcRenderer.on('deep-link', (_, { url: number }) => onClickCall?.({ number }));
    
    setState({ electron: true });
    resize(size);
  } catch (err) {
    console.warn('Electron not found');
  }
};

export const linking = ({ url }) => {
  if (ipcRenderer)
    return ipcRenderer.send?.('open', { url }); 
    
  return window.open(url, '_blank');
};
