import { useEffect, useRef } from 'react';
import { View } from 'react-native';

import { RTCView } from 'react-native-webrtc-web-shim';

import { isWeb } from '../utils';

export const Player = ({ stream, speaker, isvideo }) => {
  const ref = useRef(null);
  const backgroundColor = isvideo && '#000';

  const setStream = async () => {
    const elem = ref.current;
    await elem.setSinkId(speaker);
    elem.srcObject = stream;
  }

  useEffect(() => {
    if (!isWeb) return;
    setStream();
  }, [stream, speaker]);
  
  const defStyle = { width: '100%', height: '100%' };
  return (
    <View style={{ flex: 1, backgroundColor }} >
      {!isWeb && stream?.toURL &&
        <RTCView style={[ defStyle, { backgroundColor }]} stream={stream} objectFit={'contain'} />
      }

      {isWeb && 
        <video style={defStyle} ref={ref} autoPlay playsInline  />
      }
    </View>
  )
};
