export const init = async ({ size, onClickCall } = {}) => {
  const sforce = window.sforce;
  if (!sforce || !sforce.opencti) return;

  sforce.opencti.setSoftphonePanelHeight({ heightPX: size.height + 30 });
  sforce.opencti.setSoftphonePanelWidth({ widthPX: size.width });

  document.addEventListener('phone:ringing', () => {
    sforce.opencti.setSoftphonePanelVisibility({ visible: true });
  });

  document.addEventListener('phone:contactclick', async ({ detail: { contact = {} } }) => {
    if (!contact.id) return;

    sforce.opencti.screenPop({
      type: sforce.opencti.SCREENPOP_TYPE.SOBJECT,
      params: { recordId: contact.id },
    });
  });

  sforce.opencti.enableClickToDial();
  sforce.opencti.onClickToDial({
    listener: ({ number, ...rest } = {}) => {
      sforce.opencti.setSoftphonePanelVisibility({ visible: true });
      onClickCall?.({
        number,
        extraHeaders: Object.entries(rest).map(([key, value]) => `${key}: ${value}`)
      });
    },
  });
};
